import 'package:flutter_test/flutter_test.dart';
import 'package:posture_triage/core/indicators.dart';
import 'package:posture_triage/core/protocol.dart';

List<int> hex(String h) => [for (var i = 0; i < h.length; i += 2) int.parse(h.substring(i, i + 2), radix: 16)];

void main() {
  test('decodes a packet produced by the firmware (protocol.h packMeasurement)', () {
    // generated by firmware/lib/core/src/protocol.h, see docs/BLE_PROTOCOL.md
    const fixture =
        '01030102eb0a0cfca6046622ffff0d00008006ff5401b0b900804d0064002bfdd204df0e66f7eb0a1a00d1ff0080480f03';
    final m = Measurement.decode(hex(fixture))!;
    expect(m.state, DevState.bend);
    expect(m.seq, 513);
    expect(m.batteryMv, 3912);
    expect(m.calibrated, isTrue);
    expect(m.moving, isTrue);
    expect(m.simulated, isFalse);
    expect(m.s, [27.95, -10.12, 11.9, 88.06, -0.01]);
    expect(m.f[0], 0.13);
    expect(m.f[1].isNaN, isTrue);
    expect(m.f[4], -180.0);
    expect(m.r[0].isNaN, isTrue);
    expect(m.r[3], -7.25);
    expect(m.ind[Ind.k], 38.07);
    expect(m.ind[Ind.s], -0.47);
    expect(m.ind[Ind.r]!.isNaN, isTrue);
  });

  test('encode then decode is lossless to 0.01 degree', () {
    final m = Measurement(
      state: DevState.stand,
      seq: 70000,
      s: [1.234, -5, 30, 0, 12],
      f: [double.nan, 1, 2, 3, 4],
      r: [0, 0, 0, 0, double.nan],
      ind: {for (final i in Ind.values) i: i.index * 1.5},
      batteryMv: 4100,
      flags: MeasFlags.simulated,
    );
    final d = Measurement.decode(m.encode())!;
    expect(d.seq, 70000 & 0xFFFF);
    expect(d.s[0], closeTo(1.23, 1e-9));
    expect(d.f[0].isNaN, isTrue);
    expect(d.r[4].isNaN, isTrue);
    expect(d.ind[Ind.r], 7.5);
    expect(d.simulated, isTrue);
  });

  test('rejects short or wrong-version packets', () {
    expect(Measurement.decode(List.filled(48, 0)), isNull);
    expect(Measurement.decode([2, ...List.filled(48, 0)]), isNull);
  });

  test('triage levels match the firmware rule', () {
    final th = Thresholds.defaults();
    final r = th.limits[Ind.r]!;
    expect(r.levelOf(2.99), Risk.healthy);
    expect(r.levelOf(3.0), Risk.monitor);
    expect(r.levelOf(-4.99), Risk.monitor);
    expect(r.levelOf(5.0), Risk.refer);
    expect(worst([Risk.healthy, Risk.refer, Risk.monitor]), Risk.refer);
  });

  test('thresholds JSON round trip and validation', () {
    final t = Thresholds.fromJson({'K': [40, 10, 14], 'provisional': false});
    expect(t.limits[Ind.k]!.mu, 40);
    expect(t.limits[Ind.r]!.mon, 3); // default kept
    expect(t.provisional, isFalse);
    expect(t.validate(), isNull);
    final back = Thresholds.fromJson(t.toJson());
    expect(back.limits[Ind.k]!.ref, 14);
    expect(Thresholds.fromJson({'K': [40, 14, 10]}).validate(), isNotNull);
  });

  test('battery percentage', () {
    expect(batteryPercent(0), -1);
    expect(batteryPercent(4200), 100);
    expect(batteryPercent(3300), 0);
  });
}
